"""Seam coverage for upstream #854: the 大易 candidate window font style.

The weight axis of the candidate font rides the same per-IME config surface
as ``candFontName`` (issue #582): ``candFontWeight`` is an integer LOGFONT
weight (1-900). The neutral default ``400`` (``FW_NORMAL``) is the weight the
candidate window's LOGFONT already carries at creation, so an unset value is
byte-identical to today's paint. The house quartet
(docs/agents/cinbase-config.md) is pinned in layers:

* the key and its default exist on ``CinBaseConfig`` even when no JSON
  defines it, and ``sanitize()`` keeps configured values and repairs bad
  ones (including the 0/FW_DONTCARE hole) to the neutral default;
* all eight shipped ``python/input_methods/*/config/config.json`` carry it,
  because layer 1's ``__dict__.update`` is the only place existing users
  see a new key;
* the engine's ``applyConfig`` puts the value on the ``customizeUI`` reply
  beside ``candFontName``/``candFontSize`` (the C++ ``updateUI`` seam);
* the settings page names a control for the key and the save loop stores a
  number, falling back to the default instead of ``NaN`` when the field is
  blank or garbage (driven through the bundled node the way
  ``test_config_tool_js.py`` drives the color controls).

The three color fields from #902 (``candTextColor``,
``windowBackgroundColor``, ``selKeyColor``) keep their 0 = follow-the-system
sentinel; the save loop checks here reuse them to pin that untouched.
"""

import json
import os
import subprocess
import sys
import tempfile
import unittest
from unittest import mock

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), os.path.pardir))
for _path in (os.path.join(ROOT, "python"), os.path.dirname(os.path.abspath(__file__))):
    if _path not in sys.path:
        sys.path.insert(0, _path)

from test_cinbase_shift_to_english import CinbaseKeyHarness  # noqa: E402

NODE = os.path.join(ROOT, "node", "node.exe")
CONFIG_DIR = os.path.join(ROOT, "python", "input_methods")
CINBASE_DIR = os.path.join(ROOT, "python", "cinbase")
CONFIG_HT = os.path.join(CINBASE_DIR, "config", "config.htm")
CONFIG_JS = os.path.join(CINBASE_DIR, "config", "js", "config.js")

IME_DIRS = ("chearray", "checj", "chedayi", "cheez",
            "cheliu", "chephonetic", "chepinyin", "chesimplex")

FW_NORMAL = 400  # the weight the candidate LOGFONT already carries
FW_BOLD = 700    # the other value the two fonts in use already give
TIMEOUT_SECONDS = 60


def fresh_config():
    from cinbase.config import CinBaseConfigClass
    return CinBaseConfigClass()


class CinbaseFontWeightQuartetTests(unittest.TestCase):

    def shipped(self, ime):
        path = os.path.join(CONFIG_DIR, ime, "config", "config.json")
        with open(path, "r", encoding="utf-8") as handle:
            return json.load(handle)

    def test_the_init_default_is_the_neutral_logfont_weight(self):
        cfg = fresh_config()
        self.assertIn("candFontWeight", cfg.__dict__,
                      "candFontWeight missing from __init__")
        self.assertEqual(FW_NORMAL, cfg.candFontWeight,
                         "the default must be the weight the LOGFONT carries")

    def test_all_eight_shipped_defaults_carry_the_key(self):
        self.assertEqual(8, len(IME_DIRS))
        for ime in IME_DIRS:
            shipped = self.shipped(ime)
            self.assertIn("candFontWeight", shipped,
                          "%s: shipped default lacks candFontWeight" % ime)
            self.assertEqual(FW_NORMAL, shipped["candFontWeight"],
                             "%s: candFontWeight must ship the neutral weight" % ime)

    def test_the_settings_page_names_a_control_for_the_weight(self):
        with open(CONFIG_HT, "r", encoding="utf-8") as handle:
            page = handle.read()
        self.assertIn('id="candFontWeight"', page,
                      "no weight control beside the 字型 control")
        self.assertIn('name="candFontWeight"', page,
                      "the weight control is unnamed, the save loop skips it")

    def test_absent_or_bad_values_fall_back_to_the_neutral_weight(self):
        cfg = fresh_config()
        for bad in ("abc", "", None, 0, 901):
            cfg.candFontWeight = bad
            cfg.sanitize()
            self.assertEqual(FW_NORMAL, cfg.candFontWeight,
                             "%r must fall back to FW_NORMAL" % bad)

    def test_configured_weights_are_honored(self):
        cfg = fresh_config()
        cfg.candFontWeight = FW_BOLD
        cfg.sanitize()
        self.assertEqual(FW_BOLD, cfg.candFontWeight)
        # numeric strings from the settings page survive sanitizing
        cfg.candFontWeight = "700"
        cfg.sanitize()
        self.assertEqual(FW_BOLD, cfg.candFontWeight)

    def test_a_user_config_without_the_key_still_answers_the_default(self):
        # an APPDATA config written before the key existed must not blank the
        # weight: layer 2 only overlays the keys it carries.
        from cinbase.config import CinBaseConfigClass
        with tempfile.TemporaryDirectory() as temp_dir:
            with mock.patch.dict(os.environ, {"APPDATA": temp_dir}):
                with open(os.path.join(temp_dir, "config.json"), "w",
                          encoding="utf-8") as handle:
                    json.dump({"candFontName": "MingLiu"}, handle)
                cfg = CinBaseConfigClass()
                cfg.imeDirName = "chesimplex"
                cfg.load()
                self.assertEqual(FW_NORMAL, cfg.candFontWeight)


class CinbaseFontWeightReadSiteTests(CinbaseKeyHarness):

    def test_the_weight_rides_the_customize_ui_reply(self):
        service = self.activate_chesimplex()
        ui = service.currentReply["customizeUI"]
        self.assertIn("candFontWeight", ui,
                      "candFontWeight never reached the customizeUI reply")
        self.assertEqual(FW_NORMAL, ui["candFontWeight"])

    def test_the_configured_font_style_reaches_the_reply(self):
        service = self.activate_chesimplex()
        service.cfg.candFontName = "Noto Sans TC"
        service.cfg.fontSize = 16
        service.cfg.candFontWeight = FW_BOLD
        service.currentReply = {}

        service.cinbase.applyConfig(service)

        ui = service.currentReply["customizeUI"]
        self.assertEqual("Noto Sans TC", ui["candFontName"])
        self.assertEqual(16, ui["candFontSize"])
        self.assertEqual(FW_BOLD, ui["candFontWeight"])


class SettingsPageWeightSaveTests(unittest.TestCase):
    """The save loop stores a number for the weight control: blank or
    garbage fields fall back to the neutral default instead of NaN, the
    0/FW_DONTCARE hole collapses onto the same default, and the three #902
    color fields keep their 0 = follow-the-system sentinel untouched."""

    def drive_save_loop(self, scenarios):
        """Run the real updateConfig() once per scenario in one node call."""
        lines = [
            "var src = require('fs').readFileSync(%s, 'utf8');" % json.dumps(
                CONFIG_JS.replace("\\", "/")),
            # Faithful to jquery-1.12.4's isNumeric.
            "function isNumeric(obj) { return !isNaN(parseFloat(obj)) && isFinite(obj); }",
            # config.js touches the DOM at load; these stubs answer exactly
            # the statements that run (isIE, includeScriptFile, loadConfig).
            "var document = {",
            "  getElementsByTagName: function () { return [{ innerText: '' }]; },",
            "  createElement: function () { return { innerHTML: '',",
            "    getElementsByTagName: function () { return []; } }; } };",
            "Object.defineProperty(globalThis, 'navigator', { value:",
            "  { userAgent: 'node', appVersion: 'Trident/7.0' },",
            "  configurable: true, writable: true });",
            "function includeScriptFile() {}",
            "$.get = function (url, cb, type) { };",
            "var inputs = [];",
            "var selects = [];",
            "function $(sel) {",
            "  if (typeof sel === 'function') { return; }",
            "  return { each: function (cb) {",
            "    (sel === 'input' ? inputs : selects).forEach(",
            "      function (it, i) { cb(i, it); }); } };",
            "}",
            "$.isNumeric = isNumeric;",
            "eval(src);",
            "var results = {};",
        ]
        for name, inputs in scenarios:
            lines.append("inputs = %s;" % json.dumps(inputs))
            lines.append("updateConfig();")
            lines.append("results[%s] = checjConfig;" % json.dumps(name))
        lines.append("console.log(JSON.stringify(results));")
        harness = "\n".join(lines)
        completed = subprocess.run(
            [NODE, "-e", harness],
            cwd=ROOT,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            timeout=TIMEOUT_SECONDS,
        )
        self.assertEqual(0, completed.returncode,
                         completed.stdout.decode("utf-8", "replace"))
        return json.loads(completed.stdout.decode("utf-8", "replace"))

    def test_the_save_loop_stores_a_number_for_the_weight(self):
        if not os.path.isfile(NODE):
            self.skipTest("no bundled node/node.exe on this machine")
        weight = lambda value: {"name": "candFontWeight", "type": "text",
                                "value": value}
        scenarios = [
            ("bold", [weight("700")]),
            ("blank", [weight("")]),
            ("garbage", [weight("abc")]),
            ("zero", [weight("0")]),
            ("colors0", [
                weight(""),
                {"name": "candTextColor", "type": "text", "value": "0"},
                {"name": "windowBackgroundColor", "type": "text", "value": "0"},
                {"name": "selKeyColor", "type": "text", "value": "0"},
            ]),
        ]
        try:
            results = self.drive_save_loop(scenarios)
        except OSError as error:
            self.skipTest("bundled node.exe cannot run here: %s" % error)
        self.assertEqual(FW_BOLD, results["bold"]["candFontWeight"],
                         "a numeric field saves the configured weight")
        for case in ("blank", "garbage", "zero"):
            self.assertEqual(FW_NORMAL, results[case]["candFontWeight"],
                             "%s: must fall back to FW_NORMAL, not NaN/garbage" % case)
        # the #902 sentinel semantics stay untouched
        colors = results["colors0"]
        for key in ("candTextColor", "windowBackgroundColor", "selKeyColor"):
            self.assertEqual(0, colors[key],
                             "%s: 0 keeps the follow-the-system sentinel" % key)


